// scripts/build-icons.mjs — generate src/views/partials/icon-sprite.ejs from
// the installed ionicons package. Reads each ICONS entry, strips width/height
// and <title>, and emits one <symbol> per icon inside a single hidden <svg>.
// Run: npm run icons. The generated file is committed so runtime needs no
// node_modules/ionicons.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");

// Every icon used in the app (outline variants). See the inventory table in
// the icons commit message / README for the mapping.
const ICONS = [
    "menu-outline",
    "close-outline",
    "pencil-outline",
    "trash-outline",
    "document-text-outline",
    "sunny-outline",
    "moon-outline",
    "search-outline",
    "add-outline",
    "grid-outline",
    "list-outline",
    "albums-outline",
    "chevron-up-outline",
    "chevron-down-outline",
    "swap-vertical-outline",
    "checkmark-outline",
    "alert-circle-outline",
    "cloud-done-outline",
    "sync-outline",
    "cloud-offline-outline",
    "arrow-undo-outline",
    "reload-outline",
];

function build() {
    const svgDir = path.join(root, "node_modules", "ionicons", "dist", "svg");
    const outDir = path.join(root, "src", "views", "partials");
    const symbols = [];

    for (const name of ICONS) {
        const file = path.join(svgDir, `${name}.svg`);
        let raw;
        try {
            raw = readFileSync(file, "utf8");
        } catch {
            throw new Error(`icon not found in node_modules/ionicons: ${name}`);
        }
        // strip the root <svg> wrapper, width/height attrs and any <title>,
        // keep the inner markup (viewBox and currentColor are preserved by
        // the normalisation below)
        const inner = raw
            .replace(/^[\s\S]*?<svg[^>]*>/, "")
            .replace(/<\/svg>[\s\S]*$/, "")
            .replace(/<title[\s\S]*?<\/title>/g, "")
            .trim();
        symbols.push(
            `<symbol id="i-${name}" viewBox="0 0 512 512">${inner}</symbol>`
        );
    }

    const sprite =
        `<!-- ionicons 8.0.13 (MIT) — generated by scripts/build-icons.mjs. Do not edit. -->\n` +
        `<svg style="display:none" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">\n` +
        symbols.map((s) => `    ${s}`).join("\n") +
        `\n</svg>\n`;

    mkdirSync(outDir, { recursive: true });
    writeFileSync(path.join(outDir, "icon-sprite.ejs"), sprite);
    console.log(`wrote ${ICONS.length} symbols -> src/views/partials/icon-sprite.ejs`);
}

build();
